insert into public.dd_service_capability_requirements (canonical_sku, capability_key, requirement_code, required, source) select s.canonical_sku, 'NOTARY_PUBLIC', 'LICENSE_SERVICE', true, 'PLANNING' from public.dd_master_service_universe s where s.canonical_sku like 'DNI-05%' and not exists (select 1 from public.dd_service_capability_requirements r where r.canonical_sku=s.canonical_sku and r.requirement_code='LICENSE_SERVICE');
insert into public.dd_service_capability_requirements (canonical_sku, capability_key, requirement_code, required, source) select s.canonical_sku, 'DANI_DECLARES_PROVIDER_AGREEMENT', 'AGREEMENT_DD', true, 'PLANNING' from public.dd_master_service_universe s where s.canonical_sku like 'DNI-05%' and not exists (select 1 from public.dd_service_capability_requirements r where r.canonical_sku=s.canonical_sku and r.requirement_code='AGREEMENT_DD');